from __future__ import annotations

import time
from functools import partial

from ..exception import InvalidSSHClient


class WtsSimCommon:
    """A common class for the wtssim package."""

    def __init__(self, *args, **kwargs):
        self._tool_dir = "/opt/iphy/latest"
        self._started = False
        self._client = None
        self._port = None
        self._pid = None

    @property
    def port(self) -> int:
        """Returns number of working port."""
        return self._port

    @property
    def tool_dir(self) -> str:
        """Get directory where egate/edaemon is installed."""
        return self._tool_dir

    @tool_dir.setter
    def tool_dir(self, new_dir: str) -> None:
        """Set directory where egate/edaemon is installed.

        :param string new_dir: New directory where egate/edaemon are installed. Can be set before egate/edaemon start.
        """
        if new_dir is not None and self._started is False:
            self._tool_dir = new_dir

    def _check_client(self) -> None:
        if not hasattr(self._client, "execute_command"):
            raise InvalidSSHClient(
                "Provided client object does not have the 'execute_command' method"
            )

    def _is_tcp_port_free(self, tcp_port: int, timeout: int = 240) -> bool:
        stime = time.time()
        check_cmd = f"ss -tuln | grep -q ':{tcp_port}'"
        while time.time() - stime <= timeout:
            _, _, is_match = self._client.execute_command(check_cmd)
            # 1 = No match found (pattern does not exist in input)
            if is_match == 1:
                return True
            time.sleep(1)
        return False

    def _kill_process(self, process_cmd: str | None = None) -> bool:
        kill_cmd = (
            partial(self._kill_process_by_id, self._pid)
            if process_cmd is None
            else partial(self._kill_process_by_regexp, process_cmd)
        )
        kill_cmd()
        start = time.time()
        while time.time() - start < 5:
            if not self._process_exists():
                return True
            time.sleep(1)
        kill_cmd(force=True)

    def _kill_process_by_id(self, selector: int | None, force: bool = False) -> None:
        force = "" if force is False else "-9 "
        self._client.execute_command(rf"sudo kill {force}{selector}")

    def _kill_process_by_regexp(
        self, selector: str | None, force: bool = False
    ) -> None:
        force = "" if force is False else "-9 "
        self._client.execute_command(rf"sudo pkill {force}-f '{selector}'")

    def _process_exists(self, process_cmd: str | None = None) -> bool:
        cmd = f"ps -p {self._pid}" if process_cmd is None else f'ps -C "{process_cmd}"'
        out, err, rc = self._client.execute_command(cmd)
        return True if rc == 0 else False
